arguments.function:
() => {
  const c1 = document.createElement('canvas');
  const gl1 = c1.getContext('webgl');
  const c2 = document.createElement('canvas');
  const gl2 = c2.getContext('webgl2');
  const read = (gl) => {
    if (!gl) return null;
    const ext = gl.getExtension('WEBGL_debug_renderer_info');
    return {
      version: gl.getParameter(gl.VERSION),
      vendor: ext ? gl.getParameter(ext.UNMASKED_VENDOR_WEBGL) : gl.getParameter(gl.VENDOR),
      renderer: ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER),
      shadingLanguage: gl.getParameter(gl.SHADING_LANGUAGE_VERSION),
    };
  };
  return {
    href: location.href,
    title: document.title,
    bodyText: (document.body && document.body.innerText || '').slice(0, 500),
    userAgent: navigator.userAgent,
    webgl1: read(gl1),
    webgl2: read(gl2),
    hardwareConcurrency: navigator.hardwareConcurrency,
    deviceMemory: navigator.deviceMemory || null,
  };
}

() => {
  const text = document.body.innerText;
  const grab = (start, end) => {
    const i = text.indexOf(start);
    if (i < 0) return '';
    const j = end ? text.indexOf(end, i + start.length) : -1;
    return text.slice(i, j > i ? j : i + 4000);
  };
  return {
    graphicsFeatureStatus: grab('Graphics Feature Status', 'Version Information'),
    problems: grab('Problems Detected', 'Driver Bug Workarounds'),
    workaroundsHead: grab('Driver Bug Workarounds', 'Problems Detected').slice(0, 1500),
    version: grab('Version Information', 'Driver Information').slice(0, 2000),
    driver: grab('Driver Information', 'Compositor Information').slice(0, 2000),
    commandLine: grab('Command Line', 'Driver Bug Workarounds').slice(0, 1500),
  };
}

() => {
  const html = document.documentElement ? document.documentElement.outerHTML : '';
  return {
    title: document.title,
    ready: document.readyState,
    bodyChildCount: document.body ? document.body.childElementCount : -1,
    textLen: (document.body && document.body.innerText || '').length,
    htmlHead: html.slice(0, 1500),
    textHead: (document.body && document.body.innerText || '').slice(0, 2000),
  };
}

() => {
  const root = document.querySelector('info-view');
  const sr = root && root.shadowRoot;
  const text = sr ? sr.textContent : '';
  const lines = text.split('\n').map(s => s.trim()).filter(Boolean);
  const keys = [
    'WebGL',
    'WebGL2',
    'Canvas',
    'Hardware acceleration',
    'GPU0',
    'GL_RENDERER',
    'GL_VENDOR',
    'GL_VERSION',
    'Problems Detected',
    'Disabled Features',
    'Dawn',
    'Rasterization',
    'Compositing',
    'Video Decode',
    'Command Line',
    'Chrome version',
    'Operating system',
    'Graphics Feature Status',
    'Driver bug',
    'blocklist',
    'disabled',
    'software',
    'ANGLE',
    'Metal',
  ];
  const interesting = lines.filter(line => keys.some(k => line.toLowerCase().includes(k.toLowerCase())));
  return {
    hasShadow: !!sr,
    lineCount: lines.length,
    interesting: interesting.slice(0, 120),
    head: lines.slice(0, 80),
  };
}
